import * as React from "react";
import Canvas from "./components/canvas";
import CommandEditor from "./components/commandEditor";
import CommandInput from "./components/commandInput";
import CommandList from "./components/commandList";
import Header from "./components/header";
import HelperLayer from "./components/helperLayer";
import SkipLink from "./components/skipLink";
import TutorialPopup from "./components/tutorialPopup";
import { commandDescriptions } from "./data/commandDescriptions";
import { pathwayExamples } from "./data/pathwayExamples";
import { tutorialPages } from "./data/tutorialPages";
import "./App.css";

export const App: React.FC=<redacted-environment-value> => {
  const [showHelper, setShowHelper] = React.useState(false);
  const [activePanel, setActivePanel] = React.useState<"tips" | "examples">(
    "tips",
  );

  const handleShowHelper = (panel: "tips" | "examples") => {
    setShowHelper(true);
    setActivePanel(panel);
  };

  const closeHelper = () => {
    setShowHelper(false);
  };

  return (
    <main id="main" className="App">
      <SkipLink />
      <Header onShowHelper={handleShowHelper} />
      <div className="appMain">
        {showHelper && activePanel === "examples" && (
          <HelperLayer
            visible={true}
            panel="examples"
            onClose={closeHelper}
            examplePaths={pathwayExamples}
            descriptions={commandDescriptions}
          />
        )}
        {showHelper && activePanel === "tips" && (
          <TutorialPopup tutorialPages={tutorialPages} onClose={closeHelper} />
        )}
        <div className="editorContainer">
          <section className="editorLine" aria-label="Logo workspace">
            <CommandEditor />
            <CommandInput descriptions={commandDescriptions} />
            <Canvas />
          </section>
          <aside className="commandListLine">
            <CommandList descriptions={commandDescriptions} />
          </aside>
        </div>
      </div>
      <footer className="appFooter">
        <span>© 2026 Logo Playground</span>
        <span>Made for curious minds and bold geometry.</span>
      </footer>
    </main>
  );
};

export default App;

import { describe, expect, it, vi } from "vitest";
import type { ICommandModel } from "../models";
import { getCommandComplexity } from "../utils/commandComplexity";
import { createPlaybackPlan } from "../utils/commandPlayback";
import { Parser } from "../utils/parser";
import { pathwayExamples } from "./pathwayExamples";

const withoutIds = (commands: readonly ICommandModel[]): unknown[] =>
  commands.map((command) => ({
    name: command.name,
    ...(command.value === undefined ? {} : { value: command.value }),
    ...(command.arg2 === undefined ? {} : { arg2: command.arg2 }),
    ...(command.color === undefined ? {} : { color: command.color }),
    ...(command.color2 === undefined ? {} : { color2: command.color2 }),
    ...(command.blend === undefined ? {} : { blend: command.blend }),
    ...(command.palette === undefined ? {} : { palette: command.palette }),
    ...(command.animation === undefined
      ? {}
      : { animation: command.animation }),
    ...(command.animations === undefined
      ? {}
      : { animations: command.animations }),
    ...(command.depth === undefined ? {} : { depth: command.depth }),
    ...(command.height === undefined ? {} : { height: command.height }),
    ...(command.rotation === undefined ? {} : { rotation: command.rotation }),
    ...(command.width === undefined ? {} : { width: command.width }),
    ...(command.commands
      ? { commands: withoutIds(command.commands) }
      : {}),
  }));

describe("pathwayExamples", () => {
  it.each(pathwayExamples)(
    "$type / $name loads the command shown in its caption",
    (example) => {
      const onError = vi.fn();
      const parsedCommands = new Parser(example.path).parse(onError);

      expect(onError).not.toHaveBeenCalled();
      expect(withoutIds([example.command])).toEqual(withoutIds(parsedCommands));
    },
  );

  it("exposes every gallery scene as a named procedure", () => {
    const procedureNames = pathwayExamples.map((example) => {
      expect(example.procedures.length).toBeGreaterThanOrEqual(1);
      expect(example.path).toContain("\nend\n");
      const entryPoint =
        example.procedures[example.procedures.length - 1];
      expect(entryPoint).toBeDefined();
      expect(example.command.procedureCalls).toEqual([
        {
          arguments: [],
          name: entryPoint.name,
        },
      ]);
      return entryPoint.name;
    });

    expect(new Set(procedureNames)).toHaveLength(pathwayExamples.length);
  });

  it("extracts meaningful helper procedures from repeated scene motifs", () => {
    const examplesWithHelpers = pathwayExamples.filter(
      (example) => example.procedures.length > 1,
    );
    const helperNames = new Set(
      examplesWithHelpers.flatMap((example) =>
        example.procedures.slice(0, -1).map((procedure) => procedure.name),
      ),
    );

    expect(examplesWithHelpers.length).toBeGreaterThanOrEqual(30);
    examplesWithHelpers.forEach((example) => {
      example.procedures.slice(0, -1).forEach((helper, helperIndex) => {
        const helperPattern = new RegExp(`\\b${helper.name}\\b`, "u");
        const isCalled = example.procedures
          .slice(helperIndex + 1)
          .some((procedure) => helperPattern.test(procedure.body));
        expect(isCalled).toBe(true);
      });
    });
    [
      "dot_ring",
      "ellipse_ring",
      "move_forward",
      "move_to",
      "place_cube",
      "place_grid",
      "place_sphere",
      "reset_light",
      "square",
      "start_scene",
    ].forEach((helperName) => {
      expect(helperNames.has(helperName)).toBe(true);
    });
  });

  it("includes a varied collection of advanced infinite animations", () => {
    const motionExamples = pathwayExamples.filter(
      (example) => example.type === "motion",
    );
    const techniques = motionExamples.map((example) => example.animationFocus);

    expect(motionExamples).toHaveLength(13);
    expect(techniques.every((technique) => technique !== undefined)).toBe(true);
    expect(new Set(techniques)).toHaveLength(motionExamples.length);
    motionExamples.forEach((example) => {
      expect(example.path).toContain("anim[");
      expect(example.path).toContain("infinite");
    });
  });

  it("uses every command available in the guide", async () => {
    const { commandDescriptions } = await import("./commandDescriptions");
    const demonstrated = new Set<string>();
    const visit = (command: Readonly<ICommandModel>) => {
      demonstrated.add(command.name);
      command.commands?.forEach(visit);
    };

    pathwayExamples.forEach((example) => {
      visit(example.command);
    });

    expect([...demonstrated].sort()).toEqual(
      Object.keys(commandDescriptions).sort(),
    );
  });

  it.each(pathwayExamples)(
    "$type / $name stays within the canvas rendering limit",
    (example) => {
      expect(getCommandComplexity([example.command]).exceedsLimit).toBe(false);
    },
  );

  it("keeps a distinct rendering focus for every performance scene", () => {
    const performanceExamples = pathwayExamples.filter(
      (example) => example.type === "performance",
    );
    const focuses = performanceExamples.map(
      (example) => example.performanceFocus,
    );

    expect(performanceExamples).toHaveLength(11);
    expect(focuses.every((focus) => focus !== undefined)).toBe(true);
    expect(new Set(focuses)).toHaveLength(performanceExamples.length);
    performanceExamples.forEach((example) => {
      const entryPoint =
        example.procedures[example.procedures.length - 1];
      expect(entryPoint.optimization).toBe("lazy-playback");
      const plan = createPlaybackPlan([example.command], "lazy");
      expect(plan.storedCommands).toBeLessThan(plan.length);
    });
  });

  it.each(["Obsidian voxel arcology", "Leviathan fusion reactor"])(
    "%s remains a high-load rendering baseline",
    (name) => {
      const example = pathwayExamples.find((item) => item.name === name);

      expect(example).toBeDefined();
      if (example === undefined) {
        throw new Error(`Missing high-load example: ${name}`);
      }
      expect(
        getCommandComplexity([example.command]).operations,
      ).toBeGreaterThanOrEqual(190_000);
    },
  );
});

import * as React from "react";
import { createRoot } from "react-dom/client";
import { Application } from "./router";
import registerServiceWorker from "./registerServiceWorker";
import { BrowserRouter } from "react-router-dom";
import "./index.css";


const rootEl = document.getElementById("root");
if (!rootEl) {
  throw new Error("Failed to find #root element for React root.");
}
const root = createRoot(rootEl);
root.render(
  <React.StrictMode>
    <BrowserRouter basename={import.meta.env.BASE_URL}>
      <Application />
    </BrowserRouter>
  </React.StrictMode>,
);

registerServiceWorker();

import * as React from 'react';
import { Route, Switch } from 'react-router-dom';
import App from '../App';

export const Application = () => (
  <Switch>
    <Route exact path="/" component={App} />
  </Switch>
);

import { beforeEach, describe, expect, it } from "vitest";
import { useCommandStore } from "./commandStore";

describe("commandStore procedures", () => {
  beforeEach(() => {
    useCommandStore.setState({ commands: [], procedures: [] });
  });

  it("defines, replaces, and deletes procedures by name", () => {
    const store = useCommandStore.getState();

    store.defineProcedures([
      {
        body: "fd :size",
        name: "line",
        parameters: ["size"],
      },
    ]);
    useCommandStore.getState().defineProcedures([
      {
        body: "fd :size bk :size",
        name: "line",
        parameters: ["size"],
      },
      {
        body: "repeat 4 [ fd :size tr 90 ]",
        name: "square",
        parameters: ["size"],
      },
    ]);

    expect(useCommandStore.getState().procedures).toEqual([
      {
        body: "fd :size bk :size",
        name: "line",
        parameters: ["size"],
      },
      {
        body: "repeat 4 [ fd :size tr 90 ]",
        name: "square",
        parameters: ["size"],
      },
    ]);

    useCommandStore.getState().deleteProcedure("line");

    expect(useCommandStore.getState().procedures).toEqual([
      {
        body: "repeat 4 [ fd :size tr 90 ]",
        name: "square",
        parameters: ["size"],
      },
    ]);
  });
});

import { describe, expect, it } from "vitest";
import type { ICommandModel } from "src/models";
import { pathwayExamples } from "src/data/pathwayExamples";
import {
  getCommandComplexity,
  MAX_COMMAND_OPERATIONS,
} from "./commandComplexity";

const command = (
  name: ICommandModel["name"],
  value?: number,
  commands?: ICommandModel[],
): ICommandModel => ({
  id: 0,
  name,
  ...(value === undefined ? {} : { value }),
  ...(commands === undefined ? {} : { commands }),
});

describe("getCommandComplexity", () => {
  it("counts primitive commands", () => {
    expect(
      getCommandComplexity([
        command("fd", 10),
        command("tr", 90),
        command("penup"),
      ]),
    ).toEqual({ operations: 3, exceedsLimit: false });
  });

  it("weights complex drawing primitives by their internal canvas work", () => {
    const scene: ICommandModel[] = [
      { id: 0, name: "star", value: 9, arg2: 120 },
      { id: 0, name: "sphere", value: 90, arg2: 8 },
      { id: 0, name: "grid3d", value: 260, arg2: 12 },
    ];

    expect(getCommandComplexity(scene).operations).toBe(64);
  });

  it("weights particle spray by density", () => {
    expect(
      getCommandComplexity([
        { id: 0, name: "spray", value: 80, arg2: 450 },
      ]).operations,
    ).toBe(451);
  });

  it("counts exact repeat and nested-repeat execution cost", () => {
    const square = command("repeat", 4, [
      command("fd", 100),
      command("tr", 90),
    ]);
    const nested = command("repeat", 10, [
      command("repeat", 10, [command("fd", 1)]),
    ]);

    expect(getCommandComplexity([square]).operations).toBe(9);
    expect(getCommandComplexity([nested]).operations).toBe(111);
  });

  it("stops counting when a program exceeds its budget", () => {
    const result = getCommandComplexity(
      [command("repeat", 1_000_000, [command("fd", 1)])],
      1_000,
    );

    expect(result).toEqual({ operations: 1_001, exceedsLimit: true });
  });

  it("rejects invalid repeat values as unsafe", () => {
    expect(
      getCommandComplexity(
        [command("repeat", Number.POSITIVE_INFINITY, [command("fd", 1)])],
        100,
      ),
    ).toEqual({ operations: 101, exceedsLimit: true });
  });

  it("keeps every bundled example inside the production budget", () => {
    pathwayExamples.forEach((example) => {
      expect(
        getCommandComplexity([example.command]),
        example.name,
      ).toMatchObject({
        exceedsLimit: false,
      });
    });

    expect(MAX_COMMAND_OPERATIONS).toBeGreaterThan(0);
  });
});

import { describe, expect, it } from "vitest";
import type { ICommandModel } from "src/models";
import {
  applyEasing,
  createPlaybackPlan,
  expandPlaybackCommands,
  getAnimatedCommandAtTime,
  getCommandAnimationDuration,
  getFinalAnimatedCommand,
} from "./commandPlayback";

const command = (
  id: number,
  name: ICommandModel["name"],
  value?: number,
  commands?: ICommandModel[],
): ICommandModel => ({
  id,
  name,
  ...(value === undefined ? {} : { value }),
  ...(commands === undefined ? {} : { commands }),
});

describe("expandPlaybackCommands", () => {
  it("expands nested repeats in execution order", () => {
    const commands = [
      command(1, "fd", 10),
      command(2, "repeat", 2, [
        command(3, "tr", 90),
        command(4, "repeat", 2, [command(5, "fd", 20)]),
      ]),
    ];

    expect(expandPlaybackCommands(commands).map(({ id }) => id)).toEqual([
      1, 3, 5, 5, 3, 5, 5,
    ]);
  });

  it("ignores empty and invalid repeat blocks", () => {
    const commands = [
      command(1, "repeat", 0, [command(2, "fd", 10)]),
      command(3, "repeat", Number.POSITIVE_INFINITY, [
        command(4, "fd", 20),
      ]),
      command(5, "home"),
    ];

    expect(expandPlaybackCommands(commands).map(({ id }) => id)).toEqual([5]);
  });

  it("keeps lazy playback equivalent without storing repeated steps", () => {
    const commands = [
      command(1, "fd", 10),
      command(2, "repeat", 1000, [
        command(3, "tr", 90),
        command(4, "repeat", 4, [command(5, "fd", 20)]),
      ]),
    ];
    const expanded = createPlaybackPlan(commands);
    const lazy = createPlaybackPlan(commands, "lazy");
    const lazyIds = Array.from(
      { length: lazy.length },
      (_item, index) => lazy.get(index).id,
    );

    expect(lazyIds).toEqual(
      Array.from(
        { length: expanded.length },
        (_item, index) => expanded.get(index).id,
      ),
    );
    expect(lazy.length).toBe(5001);
    expect(lazy.storedCommands).toBe(5);
    expect(expanded.storedCommands).toBe(5001);
    expect(lazy.some(({ id }) => id === 5)).toBe(true);
  });

  it("iterates lazy plans in the same execution order", () => {
    const commands = [
      command(1, "repeat", 2, [
        command(2, "fd", 10),
        command(3, "tr", 90),
      ]),
    ];
    const ids: number[] = [];

    createPlaybackPlan(commands, "lazy").forEach(({ id }) => {
      ids.push(id);
    });

    expect(ids).toEqual([2, 3, 2, 3]);
  });

  it("advances and resets a compact playback cursor", () => {
    const plan = createPlaybackPlan(
      [
        command(1, "fd", 10),
        command(2, "repeat", 2, [
          command(3, "tr", 90),
          command(4, "repeat", 2, [command(5, "fd", 20)]),
        ]),
      ],
      "lazy",
    );
    const cursor = plan.createCursor();
    const readIds = () => {
      const ids: number[] = [];
      let next = cursor.next();
      while (next !== undefined) {
        ids.push(next.id);
        next = cursor.next();
      }
      return ids;
    };

    expect(readIds()).toEqual([1, 3, 5, 5, 3, 5, 5]);
    expect(cursor.next()).toBeUndefined();
    cursor.reset();
    expect(readIds()).toEqual([1, 3, 5, 5, 3, 5, 5]);
  });

  it("traverses a compact subrange without indexed lookup", () => {
    const plan = createPlaybackPlan(
      [
        command(1, "fd", 10),
        command(2, "repeat", 3, [
          command(3, "tr", 90),
          command(4, "repeat", 2, [command(5, "fd", 20)]),
        ]),
        command(6, "home"),
      ],
      "lazy",
    );
    const ids: number[] = [];

    plan.forEachRange(2, 9, ({ id }) => {
      ids.push(id);
    });

    expect(ids).toEqual([5, 5, 3, 5, 5, 3, 5]);
    expect(() => {
      plan.forEachRange(-1, 2, ({ id }) => {
        ids.push(id);
      });
    }).toThrow(RangeError);
    expect(() => {
      plan.forEachRange(0, plan.length + 1, ({ id }) => {
        ids.push(id);
      });
    }).toThrow(RangeError);
  });

});

describe("animated command values", () => {
  it("interpolates an authored value range", () => {
    const commandModel: ICommandModel = {
      animation: {
        cycles: 1,
        durationMs: 1000,
        easing: "linear",
        finish: 200,
        mode: "once",
        property: "value",
        start: 20,
      },
      id: 1,
      name: "fd",
      value: 200,
    };

    expect(getAnimatedCommandAtTime(commandModel, 0).value).toBe(20);
    expect(getAnimatedCommandAtTime(commandModel, 500).value).toBe(110);
    expect(getAnimatedCommandAtTime(commandModel, 1000).value).toBe(200);
  });

  it("interpolates cube rotation without changing its dimensions", () => {
    const commandModel: ICommandModel = {
      animation: {
        cycles: 1,
        durationMs: 4000,
        easing: "linear",
        finish: 360,
        mode: "once",
        property: "rotation",
        start: 0,
      },
      arg2: 90,
      id: 1,
      name: "cube",
      rotation: 360,
      value: 220,
    };

    expect(getAnimatedCommandAtTime(commandModel, 1000)).toMatchObject({
      arg2: 90,
      rotation: 90,
      value: 220,
    });
  });

  it("animates independent cube tracks on one shared timeline", () => {
    const commandModel: ICommandModel = {
      animations: [
        {
          cycles: 2,
          durationMs: 1000,
          easing: "linear",
          finish: 260,
          mode: "pingpong",
          property: "width",
          start: 120,
        },
        {
          cycles: "infinite",
          durationMs: 2000,
          easing: "linear",
          finish: 360,
          mode: "repeat",
          property: "rotation",
          start: 0,
